void send_floorplan_image(WebEmSession *session, const request *req, reply *rep) {
    const char *idx_str = webem_get_param(req, "idx");
    if (!idx_str || idx_str[0] == '\0') {
        return;
    }

    int idx = atoi(idx_str);
    void *image_data = NULL;
    size_t image_size = 0;

    if (!db_query_image(idx, &image_data, &image_size)) {
        return;
    }

    if (image_data == NULL || image_size == 0) {
        return;
    }

    char *file_ext = NULL;

    // Determine file extension based on first byte
    if (((unsigned char *)image_data)[0] == 0x47) { // 'G' for GIF
        file_ext = "gif";
    } else if (((unsigned char *)image_data)[0] == 0x89) { // for PNG
        file_ext = "png";
    } else if (((unsigned char *)image_data)[0] == 0x42) { // 'B' for BMP
        file_ext = "bmp";
    } else { // assume JPEG if unknown
        file_ext = "jpg";
    }

    char filename[64];
    snprintf(filename, sizeof(filename), "floorplan.%s", file_ext);

    rep->content_type = "application/octet-stream";
    rep->content_disposition = format("attachment; filename=\"%s\"", filename);
    rep->body = (const char *)image_data;
    rep->body_len = image_size;
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = webem_request_get_query_param(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned char* image_data;
    size_t image_size;
    if (!database_get_image_by_id(idx, &image_data, &image_size)) {
        return;
    }

    rep.content = image_data;
    rep.content_length = image_size;

    char* content_type = NULL;
    if (image_size > 0) {
        if (image_data[0] == 0x47) { // 'G' for GIF
            content_type = "image/gif";
        } else if (image_data[0] == 0x89 && image_size > 2 && image_data[1] == 0x50 && image_data[2] == 0x4E && image_data[3] == 0x47) { // PNG
            content_type = "image/png";
        } else if (image_data[0] == 0xFF && image_size > 2 && image_data[1] == 0xD8 && image_data[2] == 0xFF) { // JPEG
            content_type = "image/jpeg";
        } else {
            content_type = "application/octet-stream";
        }
    }

    char content_disposition[256];
    snprintf(content_disposition, sizeof(content_disposition), "attachment; filename=\"floorplan.%s\"",
             (content_type && strcmp(content_type, "image/gif") == 0) ? "gif" :
             (content_type && strcmp(content_type, "image/png") == 0) ? "png" :
             (content_type && strcmp(content_type, "image/jpeg") == 0) ? "jpg" : "bin");

    webem_reply_set_header(rep, "Content-Type", content_type ? content_type : "application/octet-stream");
    webem_reply_set_header(rep, "Content-Disposition", content_disposition);
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = webem_request_get_param(&req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned int image_id = atoi(idx);
    unsigned char* image_data = NULL;
    size_t image_size = 0;

    if (!db_get_image(image_id, &image_data, &image_size)) {
        return;
    }

    const char* content_disposition = "attachment";
    char* filename = NULL;

    if (image_size > 0) {
        switch (image_data[0]) {
            case 0x47: /* 'G' for GIF */
                filename = "floorplan.gif";
                break;
            case 0x89: /* for PNG */
                filename = "floorplan.png";
                break;
            case 0x46: /* 'F' for some formats */
                filename = "floorplan.bmp";
                break;
            default:
                filename = "floorplan.bin";
        }
        content_disposition = apr_psprintf(rep.pool, "%s; filename=\"%s\"", content_disposition, filename);
    }

    rep.status = 200;
    rep.headers = apr_table_make(rep.pool, 5);
    apr_table_set(rep.headers, "Content-Type", "application/octet-stream");
    apr_table_set(rep.headers, "Content-Disposition", content_disposition);
    rep.body = image_data;
    rep.body_len = image_size;
}

void handleFloorplanRequest(WebEmSession* session, const request* req, reply* rep) {
    const char* idx = requestGetParameter(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned char* imageData = queryDatabaseForImage(idx);
    if (!imageData) {
        return;
    }

    // Determine file extension based on the first byte of the image data
    char* fileExtension = NULL;
    if (imageData[0] == 0x89) { // PNG signature
        fileExtension = "png";
    } else if (imageData[0] == 0x47) { // GIF signature
        fileExtension = "gif";
    } else if (imageData[0] == 0x42 && imageData[1] == 0x4D) { // BMP signature
        fileExtension = "bmp";
    } else if (imageData[0] == 0xFF && imageData[1] == 0xD8) { // JPEG signature
        fileExtension = "jpg";
    } else {
        free(imageData);
        return;
    }

    replySetContent(rep, imageData, strlen((char*)imageData));
    char header[256];
    snprintf(header, sizeof(header), "attachment; filename=floorplan.%s", fileExtension);
    replyAddHeader(rep, "Content-Disposition", header);

    free(imageData);
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = request_get_param(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned char* image_data = NULL;
    size_t image_size = 0;
    if (!database_get_image(idx, &image_data, &image_size)) {
        return;
    }

    if (image_size == 0 || image_data == NULL) {
        free(image_data);
        return;
    }

    reply_set_content(rep, image_data, image_size);

    const char* ext = NULL;
    if (image_data[0] == 0x47) {
        ext = "gif";
    } else if (image_data[0] == 0x89 && image_size > 1 && image_data[1] == 0x50) {
        ext = "png";
    } else if (image_data[0] == 0x42 && image_size > 1 && image_data[1] == 0x4D) {
        ext = "bmp";
    } else if (image_data[0] == 0xFF && image_size > 1 && image_data[1] == 0xD8) {
        ext = "jpg";
    } else {
        ext = "bin";
    }

    char filename[256];
    snprintf(filename, sizeof(filename), "floorplan.%s", ext);
    reply_add_header(rep, "Content-Disposition", "attachment; filename=\"%s\"", filename);

    free(image_data);
}
